def describe_tags(self, resource_arns: List[str]) -> Dict[str, Dict[str, str]]:
    result = {}
    for arn in resource_arns:
        # Validate ARN format
        if not arn.startswith('arn:aws:elasticloadbalancing:'):
            raise RESTError(
                'LoadBalancerNotFound',
                f'Load balancer {arn} not found'
            )
        result[arn] = self.tagging_service.get_tag_dict_for_resource(arn)
    return result
